import type { components, paths } from './schema';

/**
 * Shorthands over the generated OpenAPI types (`schema.ts`, regenerated by
 * `pnpm --filter @qualor/ui api` from server/openapi.json). The UI never declares an API shape by
 * hand (brief §5.7: the UI talks to the server only through the generated client).
 */
export type Problem = components['schemas']['Problem'];

type JsonOf<R> = R extends { content: { 'application/json': infer T } } ? T : never;

/** The JSON body of an operation's 200 or 201 response. */
export type ResponseBody<P extends keyof paths, M extends keyof paths[P]> = paths[P][M] extends {
  responses: infer R;
}
  ? R extends { 200: infer Ok }
    ? JsonOf<Ok>
    : R extends { 201: infer Created }
      ? JsonOf<Created>
      : never
  : never;

/** The JSON body of an operation's 202 response (a request accepted for a job). */
export type AcceptedBody<P extends keyof paths, M extends keyof paths[P]> = paths[P][M] extends {
  responses: { 202: infer Accepted };
}
  ? JsonOf<Accepted>
  : never;

/** One item of a keyset-paginated list response (`{ items, nextCursor }`). */
export type ItemOf<P extends keyof paths> =
  ResponseBody<P, 'get' & keyof paths[P]> extends { items: (infer T)[] } ? T : never;

/** The JSON request body of an operation. */
export type RequestBody<P extends keyof paths, M extends keyof paths[P]> = paths[P][M] extends {
  requestBody?: { content: { 'application/json': infer B } };
}
  ? B
  : never;

export type Me = ResponseBody<'/api/v0/auth/me', 'get'>;
/** `GET /auth/methods` (sso-scim.md §10): the password policy and the SSO providers. */
export type AuthMethods = ResponseBody<'/api/v0/auth/methods', 'get'>;
export type SsoProvider = AuthMethods['providers'][number];
/** `POST /auth/invitations/inspect` (mail E2): who an invitation link is for. */
export type InvitationInfo = ResponseBody<'/api/v0/auth/invitations/inspect', 'post'>;
export type Organization = ItemOf<'/api/v0/organizations'>;

/** A role grant on one project (rbac-audit.md §16, `GET /projects/{id}/members`). */
export type ProjectGrant = ItemOf<'/api/v0/projects/{id}/members'>;
/** The roles a project grant may carry: `admin` is organisation-wide only (§3.2). */
export type GrantRole = ProjectGrant['role'];

/** `GET /organizations/{id}/jira`: the connection (or null) and whether Qualor links can be written. */
export type JiraSettingsAnswer = ResponseBody<'/api/v0/organizations/{id}/jira', 'get'>;
export type JiraConnection = NonNullable<JiraSettingsAnswer['connection']>;
/** `POST /organizations/{id}/jira/test`. */
export type JiraTestResult = ResponseBody<'/api/v0/organizations/{id}/jira/test', 'post'>;

/** `GET /projects/{id}/jira`: the mapping, the organisation's connection and the rule's switches. */
export type JiraProjectSettings = ResponseBody<'/api/v0/projects/{id}/jira', 'get'>;
export type JiraMapping = NonNullable<JiraProjectSettings['mapping']>;
/** `GET /projects/{id}/jira/projects`: one Jira project of the picker. */
export type JiraPickedProject = ItemOf<'/api/v0/projects/{id}/jira/projects'>;
/** `GET /projects/{id}/jira/issue-types`: an issue type of a Jira project. */
export type JiraIssueType = ItemOf<'/api/v0/projects/{id}/jira/issue-types'>;
/**
 * A finding's Jira link, as issue and vulnerability items embed it (`jira`, null while the finding
 * has none: a dismissed link reads as none).
 */
export type JiraLink = NonNullable<ItemOf<'/api/v0/issues'>['jira']>;
/**
 * One item of `POST /projects/{id}/jira/links`: the issue or the vulnerability, its link, and why
 * it was skipped (`ALREADY_LINKED` carries the link it has).
 */
export type JiraLinkItem = AcceptedBody<
  '/api/v0/projects/{id}/jira/links',
  'post'
>['items'][number];
